package envgroups

import (
	"context"
	"fmt"
	"github.com/bex-co/bex/lego/backend/internal/core"
	"github.com/bex-co/bex/lego/backend/internal/core/coretest"
	"strings"
	"testing"
)

type qaA633CountStore struct {
	*fakeStore
	metaGets, lists int
}

func (s *qaA633CountStore) Get(ctx context.Context, path string) (map[string]string, error) {
	if strings.HasSuffix(path, "/meta") {
		s.metaGets++
	}
	return s.fakeStore.Get(ctx, path)
}
func (s *qaA633CountStore) List(ctx context.Context, path string) ([]string, error) {
	s.lists++
	return s.fakeStore.List(ctx, path)
}
func TestQaA633AdmissionReadGrowth(t *testing.T) {
	for _, scope := range []string{"", "tea-a"} {
		for _, retired := range []int{0, 20, 100} {
			store := &qaA633CountStore{fakeStore: newFakeStore()}
			svc := newService(store)
			svc.MaxEnvGroups = 100
			var ctx context.Context = context.Background()
			if scope != "" {
				svc.Workspace = coretest.Members{"dana": {"tea-a"}}
				ctx = core.WithIdentity(ctx, core.Identity{Subject: "dana", Method: "session"})
			}
			source, err := svc.CreateEnvGroup(ctx, CreateEnvGroupRequest{Name: "qa-a633-source", OwnerID: scope})
			if err != nil {
				t.Fatal(err)
			}
			for i := 0; i < retired; i++ {
				g, e := svc.CreateEnvGroup(ctx, CreateEnvGroupRequest{Name: fmt.Sprintf("qa-a633-retired-%d", i), OwnerID: scope})
				if e != nil {
					t.Fatal(e)
				}
				if e = svc.DeleteEnvGroup(ctx, g.ID); e != nil {
					t.Fatal(e)
				}
			}
			listed, e := svc.ListEnvGroups(ctx, scope)
			if e != nil || len(listed) != 1 {
				t.Fatalf("live before clone=%d err=%v", len(listed), e)
			}
			store.metaGets = 0
			store.lists = 0
			clone, e := svc.CloneEnvGroup(ctx, source.ID, CloneEnvGroupRequest{Name: "qa-a633-clone", OwnerID: scope})
			if e != nil || clone.ID == source.ID || len(clone.ServiceLinks) != 0 {
				t.Fatalf("clone=%+v err=%v", clone, e)
			}
			t.Logf("scope=%q retired=%d activeBefore=1 cloneMetaGets=%d cloneLists=%d", scope, retired, store.metaGets, store.lists)
		}
	}
}
